  "Samsoom knows our catalogue, grades, hours and shipping. It finds the part, explains the grade, and hands you to a person on WhatsApp the second you need one.": "Samsoom-ന് ഞങ്ങളുടെ കാറ്റലോഗ്, ഗ്രേഡുകൾ, സമയം, ഷിപ്പിംഗ് എല്ലാം അറിയാം. പാർട്ട് കണ്ടെത്തി, ഗ്രേഡ് വിശദീകരിച്ച്, ആവശ്യമുള്ള നിമിഷം WhatsApp-ൽ ഒരാളുമായി ബന്ധിപ്പിക്കുന്നു.",
  "Do you have a Galaxy A54 battery?": "Galaxy A54 ബാറ്ററി ഉണ്ടോ?",
  "Which grade should I pick for an iPhone 13 screen?": "iPhone 13 സ്ക്രീനിന് ഏത് ഗ്രേഡ് തിരഞ്ഞെടുക്കണം?",
