  "Remove the photo": "ഫോട്ടോ നീക്കുക",
  "Attach a photo of the phone": "ഫോണിന്റെ ഫോട്ടോ ചേർക്കുക",
  "Add to a list": "ഒരു ലിസ്റ്റിൽ ചേർക്കുക",
  "My lists": "എന്റെ ലിസ്റ്റുകൾ",
  "No lists yet. Name one, e.g. “Shop order June”.": "ഇതുവരെ ലിസ്റ്റുകളില്ല. ഒന്നിന് പേരിടൂ, ഉദാ. “ജൂൺ ഷോപ്പ് ഓർഡർ”.",
  "New list name": "പുതിയ ലിസ്റ്റിന്റെ പേര്",
  "See my lists": "എന്റെ ലിസ്റ്റുകൾ കാണുക",
  "Request it": "അഭ്യർത്ഥിക്കുക",
  "Reviews open once we have confirmed your order of this part, so every review is a verified purchase.": "ഈ പാർട്ടിന്റെ ഓർഡർ ഞങ്ങൾ സ്ഥിരീകരിച്ചശേഷം റിവ്യൂ തുറക്കും, അതിനാൽ ഓരോ റിവ്യൂവും സ്ഥിരീകരിച്ച വാങ്ങലാണ്.",
  "Only customers who bought this part can review it, after we confirm their order.": "ഈ പാർട്ട് വാങ്ങിയ ഉപഭോക്താക്കൾക്ക് മാത്രമേ ഓർഡർ സ്ഥിരീകരിച്ചശേഷം റിവ്യൂ ചെയ്യാനാകൂ.",
  "Prices and stock shown are test data while the shop is set up": "ഷോപ്പ് തയ്യാറാകുന്നതുവരെ വിലയും സ്റ്റോക്കും ടെസ്റ്റ് ഡാറ്റയാണ്",
