  'That code is wrong or has expired. Ask for a new one.': 'കോഡ് തെറ്റാണ് അല്ലെങ്കിൽ കാലഹരണപ്പെട്ടു. പുതിയത് ചോദിക്കൂ.',
  'Too many tries. Please wait a minute and try again.': 'വളരെയധികം ശ്രമങ്ങൾ. ഒരു മിനിറ്റ് കാത്തിരുന്ന് വീണ്ടും ശ്രമിക്കൂ.',
  'That e-mail address does not look right.': 'ഈ ഇ-മെയിൽ വിലാസം ശരിയല്ലെന്ന് തോന്നുന്നു.',
