  'More…': 'കൂടുതൽ…',
  'Everything on this website and in its systems (photos, designs, texts, prices and data) belongs to Sam Electronics and is protected by the copyright laws of the United Arab Emirates, including Federal Decree-Law No. 38 of 2021. A screenshot for your own reference is fine; copying, sharing or publishing it without our written permission is not.': 'ഈ വെബ്സൈറ്റിലും സിസ്റ്റങ്ങളിലുമുള്ള എല്ലാം (ഫോട്ടോകൾ, ഡിസൈനുകൾ, എഴുത്തുകൾ, വിലകൾ, ഡാറ്റ) Sam Electronics-ന്റേതാണ്, 2021-ലെ 38-ാം നമ്പർ ഫെഡറൽ ഡിക്രി-നിയമം ഉൾപ്പെടെ UAE പകർപ്പവകാശ നിയമങ്ങളാൽ സംരക്ഷിതം. സ്വന്തം ആവശ്യത്തിന് സ്ക്രീൻഷോട്ട് കുഴപ്പമില്ല; ഞങ്ങളുടെ രേഖാമൂലമുള്ള അനുമതിയില്ലാതെ പകർത്തുന്നതും പങ്കിടുന്നതും പ്രസിദ്ധീകരിക്കുന്നതും പാടില്ല.',
  'Your connection says you are somewhere else than your device does. Prices, stock and delivery here depend on where you really are, and hiding your location goes against our terms of use. Please switch the VPN off for real prices and delivery times.': 'നിങ്ങളുടെ കണക്ഷൻ ഉപകരണത്തിൽ നിന്ന് വ്യത്യസ്തമായ സ്ഥലം കാണിക്കുന്നു. വിലയും സ്റ്റോക്കും ഡെലിവറിയും നിങ്ങൾ യഥാർത്ഥത്തിൽ എവിടെയാണ് എന്നതിനെ ആശ്രയിക്കുന്നു, സ്ഥലം മറയ്ക്കുന്നത് ഞങ്ങളുടെ നിബന്ധനകൾക്ക് വിരുദ്ധമാണ്. യഥാർത്ഥ വിലയ്ക്കും സമയത്തിനും VPN ഓഫാക്കൂ.',
  'Prices and delivery depend on where you really are. Please switch the VPN off.': 'വിലയും ഡെലിവറിയും നിങ്ങൾ യഥാർത്ഥത്തിൽ എവിടെയാണ് എന്നതിനെ ആശ്രയിച്ചിരിക്കുന്നു. ദയവായി VPN ഓഫാക്കൂ.',
  'Why am I seeing this?': 'എന്തുകൊണ്ട് ഇത് കാണുന്നു?',
  'Keeping it for yourself is fine; sharing or publishing it needs our permission.': 'സ്വന്തമായി സൂക്ഷിക്കുന്നത് കുഴപ്പമില്ല; പങ്കിടാനോ പ്രസിദ്ധീകരിക്കാനോ ഞങ്ങളുടെ അനുമതി വേണം.',
