  'Parts, grades, prices, repairs, shipping, opening hours: I know the shop inside out. Spelling mistakes are fine, and I speak your language.': 'ഭാഗങ്ങൾ, ഗ്രേഡുകൾ, വിലകൾ, റിപ്പയർ, ഷിപ്പിംഗ്, സമയം: കട എനിക്ക് നന്നായി അറിയാം. അക്ഷരത്തെറ്റുകൾ കുഴപ്പമില്ല, നിങ്ങളുടെ ഭാഷയും ഞാൻ സംസാരിക്കും.',
  'Right now:': 'ഇപ്പോൾ:',
  'Sam Circuit': 'Sam Circuit',
  'Samsoom can make mistakes. Prices and stock are confirmed by the team on WhatsApp.': 'Samsoom-ന് തെറ്റ് പറ്റാം. വിലയും സ്റ്റോക്കും ടീം WhatsApp-ൽ സ്ഥിരീകരിക്കും.',
  'Trade prices unlock once your trade account is approved. Send a bulk list and we quote it the same day.': 'ട്രേഡ് അക്കൗണ്ട് അംഗീകരിച്ചാൽ മൊത്തവില ലഭിക്കും. ബൾക്ക് ലിസ്റ്റ് അയച്ചാൽ അന്നുതന്നെ ക്വോട്ട് തരാം.',
  'What is the difference between Original, OLED and Incell?': 'Original, OLED, Incell എന്നിവ തമ്മിലുള്ള വ്യത്യാസം എന്താണ്?',
