  'Back online': 'വീണ്ടും ഓൺലൈനിൽ',
  'Everything works again.': 'എല്ലാം വീണ്ടും പ്രവർത്തിക്കുന്നു.',
  'A flexible OLED panel made to the original spec: deep blacks and true colors, close to original at a lower price.': 'ഒറിജിനൽ സ്പെക്കിൽ നിർമിച്ച ഫ്ലെക്സിബിൾ OLED പാനൽ: ആഴമുള്ള കറുപ്പും യഥാർത്ഥ നിറങ്ങളും, കുറഞ്ഞ വിലയിൽ ഒറിജിനലിനോട് അടുത്ത്.',
  'A good, tested aftermarket part for the best price. Ideal when cost matters most.': 'മികച്ച വിലയ്ക്ക് നല്ല, പരിശോധിച്ച ആഫ്റ്റർമാർക്കറ്റ് ഭാഗം. ചെലവ് പ്രധാനമാകുമ്പോൾ ഉത്തമം.',
