  'Every screen we sell is checked on the bench for touch, color and brightness before it leaves Deira. Pick the grade that fits the job and the budget.': 'ഞങ്ങൾ വിൽക്കുന്ന ഓരോ സ്ക്രീനും ദേര വിടുന്നതിന് മുമ്പ് ടച്ച്, നിറം, തിളക്കം എന്നിവയ്ക്കായി ബെഞ്ചിൽ പരിശോധിക്കുന്നു. ജോലിക്കും ബജറ്റിനും അനുയോജ്യമായ ഗ്രേഡ് തിരഞ്ഞെടുക്കൂ.',
