  'Genuine cells in every grade': 'ഓരോ ഗ്രേഡിലും യഥാർത്ഥ സെല്ലുകൾ',
  'Capacity checked before dispatch': 'അയയ്ക്കുന്നതിന് മുമ്പ് ശേഷി പരിശോധിച്ചു',
  'Packed safely for shipping': 'ഷിപ്പിംഗിനായി സുരക്ഷിതമായി പാക്ക് ചെയ്തു',
  'Back covers in every color, cut to the exact fit of each model, with the camera ring and adhesive where the model needs them.': 'എല്ലാ നിറങ്ങളിലുമുള്ള ബാക്ക് കവറുകൾ, ഓരോ മോഡലിനും കൃത്യമായ ഫിറ്റ്, ആവശ്യമുള്ളിടത്ത് ക്യാമറ റിംഗും പശയും സഹിതം.',
  'Every color per model': 'ഓരോ മോഡലിനും എല്ലാ നിറവും',
  'Exact factory fit': 'കൃത്യമായ ഫാക്ടറി ഫിറ്റ്',
