  'Front and rear camera modules, focus-tested on the bench so the first photo after the repair is sharp.': 'മുൻ, പിൻ ക്യാമറ മൊഡ്യൂളുകൾ, റിപ്പയറിന് ശേഷമുള്ള ആദ്യ ഫോട്ടോ വ്യക്തമാകാൻ ബെഞ്ചിൽ ഫോക്കസ് പരിശോധിച്ചത്.',
  'Front and rear modules': 'മുൻ, പിൻ മൊഡ്യൂളുകൾ',
  'Focus tested on the bench': 'ബെഞ്ചിൽ ഫോക്കസ് പരിശോധിച്ചു',
  'For every major brand': 'എല്ലാ പ്രധാന ബ്രാൻഡുകൾക്കും',
  'Mid-frames and housings for every major model: buttons, antenna lines and screw holes exactly where the factory put them.': 'എല്ലാ പ്രധാന മോഡലുകൾക്കുമുള്ള മിഡ്-ഫ്രെയിമുകളും ഹൗസിംഗുകളും: ബട്ടണുകൾ, ആന്റിന ലൈനുകൾ, സ്ക്രൂ ദ്വാരങ്ങൾ ഫാക്ടറി വെച്ച അതേ സ്ഥാനത്ത്.',
  'Factory-fit mid-frames': 'ഫാക്ടറി-ഫിറ്റ് മിഡ്-ഫ്രെയിമുകൾ',
  'Housings for every major model': 'എല്ലാ പ്രധാന മോഡലുകൾക്കും ഹൗസിംഗുകൾ',
  'Ready for a full rebuild': 'പൂർണ പുനർനിർമ്മാണത്തിന് തയ്യാർ',
  'We ship from Deira every day to the Middle East, Africa, Europe and Asia. Every order is tracked and securely packed; shipping is quoted with your order.': 'ദേരയിൽ നിന്ന് എല്ലാ ദിവസവും മിഡിൽ ഈസ്റ്റ്, ആഫ്രിക്ക, യൂറോപ്പ്, ഏഷ്യ എന്നിവിടങ്ങളിലേക്ക് അയയ്ക്കുന്നു. ഓരോ ഓർഡറും ട്രാക്ക് ചെയ്യുകയും സുരക്ഷിതമായി പാക്ക് ചെയ്യുകയും ചെയ്യുന്നു; ഷിപ്പിംഗ് ഓർഡറിനൊപ്പം ക്വോട്ട് ചെയ്യും.',
  'Tracked, every order': 'ഓരോ ഓർഡറും ട്രാക്ക് ചെയ്യുന്നു',
  'Securely packed by hand': 'കൈകൊണ്ട് സുരക്ഷിതമായി പാക്ക് ചെയ്തത്',
  'Quoted with your order': 'നിങ്ങളുടെ ഓർഡറിനൊപ്പം ക്വോട്ട് ചെയ്യും',
  'Trade prices for repair shops and resellers once your trade account is approved. Send a bulk list and we quote it the same day.': 'ട്രേഡ് അക്കൗണ്ട് അംഗീകരിച്ചാൽ റിപ്പയർ ഷോപ്പുകൾക്കും റീസെല്ലർമാർക്കും മൊത്തവില. ബൾക്ക് ലിസ്റ്റ് അയച്ചാൽ അന്നുതന്നെ ക്വോട്ട്.',
  'Our bench in Deira replaces screens and batteries and fixes board faults. Every repair is tested before you collect it.': 'ദേരയിലെ ഞങ്ങളുടെ ബെഞ്ച് സ്ക്രീനുകളും ബാറ്ററികളും മാറ്റുകയും ബോർഡ് തകരാറുകൾ പരിഹരിക്കുകയും ചെയ്യുന്നു. എടുക്കുന്നതിന് മുമ്പ് ഓരോ റിപ്പയറും പരിശോധിക്കും.',
  'Screens, batteries, ports and boards': 'സ്ക്രീനുകൾ, ബാറ്ററികൾ, പോർട്ടുകൾ, ബോർഡുകൾ',
  'Tested before you collect': 'എടുക്കുന്നതിന് മുമ്പ് പരിശോധിച്ചു',
  'Price range in the estimator': 'എസ്റ്റിമേറ്ററിൽ വില പരിധി',
  'Charging, power and button flex cables for every major model, checked for fit and contact before they ship.': 'എല്ലാ പ്രധാന മോഡലുകൾക്കുമുള്ള ചാർജിംഗ്, പവർ, ബട്ടൺ ഫ്ലെക്സ് കേബിളുകൾ, അയയ്ക്കുന്നതിന് മുമ്പ് ഫിറ്റും കോൺടാക്റ്റും പരിശോധിച്ചത്.',
