  'Yes, for approved trade accounts. Prices step down as your order grows:': 'അതെ, അംഗീകൃത ട്രേഡ് അക്കൗണ്ടുകൾക്ക്. ഓർഡർ വലുതാകുന്തോറും വില കുറയും:',
