  'No levels and no points: management chooses who receives it.': 'ലെവലുകളോ പോയിന്റുകളോ ഇല്ല: ആർക്ക് നൽകണമെന്ന് മാനേജ്മെന്റ് തീരുമാനിക്കും.',
