  'This part of the site is still being built. Everything you need is on the home page in the meantime.': 'സൈറ്റിന്റെ ഈ ഭാഗം ഇപ്പോഴും നിർമാണത്തിലാണ്. അതുവരെ ആവശ്യമുള്ളതെല്ലാം ഹോം പേജിലുണ്ട്.',
