  'Tell me a model and a part to compare, for example: iPhone 13 screen.': 'താരതമ്യം ചെയ്യാൻ ഒരു മോഡലും ഭാഗവും പറയൂ, ഉദാ: iPhone 13 സ്ക്രീൻ.',
