  'Reach the team the way you like. Your chat with Samsoom can come along.': 'നിങ്ങൾക്ക് ഇഷ്ടമുള്ള വഴിയിൽ ടീമിനെ ബന്ധപ്പെടൂ. സാംസൂമുമായുള്ള ചാറ്റും കൂടെ വരാം.',
