  'The big box plays our latest offers. Pick a tab, a part or a brand and it shows that topic\'s own deals.': 'വലിയ ബോക്സിൽ പുതിയ ഓഫറുകൾ കാണാം. ഒരു ടാബ്, ഭാഗം അല്ലെങ്കിൽ ബ്രാൻഡ് തിരഞ്ഞെടുത്താൽ അതിന്റെ ഡീലുകൾ കാണിക്കും.',
  'The coloured tag is the quality (Original, OLED, Incell, AAA and more). The dark tag with a light is who made it.': 'നിറമുള്ള ടാഗ് ഗുണനിലവാരം (ഒറിജിനൽ, OLED, Incell, AAA...). ലൈറ്റുള്ള ഇരുണ്ട ടാഗ് നിർമ്മാതാവ്.',
  'Star a part to keep it in My Bench. The two-cards button adds it to Compare: up to three parts side by side.': 'സ്റ്റാർ ചെയ്ത് My Bench-ൽ സൂക്ഷിക്കാം. രണ്ട് കാർഡ് ബട്ടൺ താരതമ്യത്തിൽ ചേർക്കും: മൂന്ന് ഭാഗങ്ങൾ വരെ.',
  'Sort by price, newest or best match, and switch between the grid and the list.': 'വില, പുതിയത്, മികച്ച പൊരുത്തം എന്നിവ അനുസരിച്ച് ക്രമീകരിക്കാം; ഗ്രിഡും ലിസ്റ്റും മാറ്റാം.',
  'Repair shops and traders: apply once, and every part shows your trade price.': 'റിപ്പയർ ഷോപ്പുകളും വ്യാപാരികളും: ഒരിക്കൽ അപേക്ഷിച്ചാൽ എല്ലാ ഭാഗത്തിലും നിങ്ങളുടെ ട്രേഡ് വില കാണാം.',
