  'Screens and batteries for P, Mate and Nova, every one tested in Deira.': 'P, Mate, Nova എന്നിവയ്ക്ക് സ്ക്രീനുകളും ബാറ്ററികളും, ഓരോന്നും ദേരയിൽ പരിശോധിച്ചത്.',
  'Shop Huawei': 'Huawei കാണൂ',
  'Pixel screens, sharp as day one.': 'Pixel സ്ക്രീനുകൾ, ആദ്യ ദിവസം പോലെ തെളിഞ്ഞത്.',
  'Original and OLED screens for Pixel 6 to the newest, with a written warranty.': 'Pixel 6 മുതൽ പുതിയത് വരെ ഒറിജിനൽ, OLED സ്ക്രീനുകൾ, എഴുതിയ വാറന്റിയോടെ.',
