  'The most repaired phones in the region, with parts at trade prices.': 'മേഖലയിൽ ഏറ്റവും കൂടുതൽ റിപ്പയർ ചെയ്യുന്ന ഫോണുകൾ, ട്രേഡ് വിലയിൽ ഭാഗങ്ങൾ.',
