  'Read the full terms': 'മുഴുവൻ നിബന്ധനകളും വായിക്കുക',
  'Save the phones you fix most. I will mark every part that fits them.': 'നിങ്ങൾ കൂടുതൽ നന്നാക്കുന്ന ഫോണുകൾ സേവ് ചെയ്യൂ. അവയ്ക്ക് യോജിക്കുന്ന എല്ലാ ഭാഗങ്ങളും ഞാൻ അടയാളപ്പെടുത്തും.',
  'Screenshots are for your own use, and every one carries our watermark. Sharing or publishing them needs our permission.': 'സ്ക്രീൻഷോട്ടുകൾ നിങ്ങളുടെ സ്വന്തം ഉപയോഗത്തിനുള്ളതാണ്, ഓരോന്നിലും ഞങ്ങളുടെ വാട്ടർമാർക്കുണ്ട്. പങ്കിടാനോ പ്രസിദ്ധീകരിക്കാനോ ഞങ്ങളുടെ അനുമതി വേണം.',
  'Every conversation you had with Samsoom on this device. Open one to carry on.': 'ഈ ഉപകരണത്തിൽ Samsoom-മായി നടത്തിയ എല്ലാ സംഭാഷണങ്ങളും. തുടരാൻ ഒന്ന് തുറക്കൂ.',
  'Every order, with its status. We confirm stock and price on WhatsApp before you pay.': 'ഓരോ ഓർഡറും അതിന്റെ നിലയോടെ. പണമടയ്ക്കുന്നതിന് മുമ്പ് WhatsApp-ൽ സ്റ്റോക്കും വിലയും സ്ഥിരീകരിക്കും.',
  'Everything the bell told you: orders, repairs, stock alerts and offers.': 'മണി അറിയിച്ചതെല്ലാം: ഓർഡറുകൾ, റിപ്പയറുകൾ, സ്റ്റോക്ക് അലേർട്ടുകൾ, ഓഫറുകൾ.',
  'The phones you fix or own. The shop marks every part that fits them, and Find My Part opens on them.': 'നിങ്ങൾ നന്നാക്കുന്ന അല്ലെങ്കിൽ ഉപയോഗിക്കുന്ന ഫോണുകൾ. യോജിക്കുന്ന എല്ലാ ഭാഗങ്ങളും ഷോപ്പ് അടയാളപ്പെടുത്തും, Find My Part അവയിൽ തന്നെ തുറക്കും.',
  'Your cart, the parts you saved for later, your stars and your price & stock alerts.': 'നിങ്ങളുടെ കാർട്ട്, പിന്നീടേക്ക് സേവ് ചെയ്ത ഭാഗങ്ങൾ, നക്ഷത്രങ്ങൾ, വില-സ്റ്റോക്ക് അലേർട്ടുകൾ.',
  'Your details, how we reach you, and your language.': 'നിങ്ങളുടെ വിവരങ്ങൾ, ഞങ്ങൾ ബന്ധപ്പെടേണ്ട വഴി, നിങ്ങളുടെ ഭാഷ.',
  'Your repair tickets with their progress, and a warranty check for any order or repair.': 'നിങ്ങളുടെ റിപ്പയർ ടിക്കറ്റുകളും പുരോഗതിയും, ഏത് ഓർഡറിനും റിപ്പയറിനും വാറന്റി പരിശോധനയും.',
  'Add the businesses you buy for: details, trade licence, TRN and every location. Orders can be placed for a company.': 'നിങ്ങൾ വാങ്ങുന്ന ബിസിനസുകൾ ചേർക്കൂ: വിവരങ്ങൾ, ട്രേഡ് ലൈസൻസ്, TRN, എല്ലാ സ്ഥലങ്ങളും. ഒരു കമ്പനിയുടെ പേരിൽ ഓർഡർ നൽകാം.',
  'Write to the team here: they answer from the Control Room during opening hours, and you get an e-mail when they do.': 'ഇവിടെ ടീമിന് എഴുതൂ: പ്രവൃത്തി സമയത്ത് Control Room-ൽ നിന്ന് മറുപടി നൽകും, അപ്പോൾ നിങ്ങൾക്ക് ഇ-മെയിൽ ലഭിക്കും.',
  'We will message you when the price drops or stock is back (e-mail alerts start when the database is connected).': 'വില കുറയുമ്പോഴോ സ്റ്റോക്ക് തിരികെ വരുമ്പോഴോ സന്ദേശം അയയ്ക്കും (ഡാറ്റാബേസ് ബന്ധിപ്പിച്ചാൽ ഇ-മെയിൽ അലേർട്ടുകൾ തുടങ്ങും).',
