  'Copying our design, colours, layout, structure, look, characters (including Samsoom), texts or ideas, or using them wrongly or falsely (for example to look like Sam Electronics or to suggest you work with us), is not allowed and can be punished under UAE law.': 'ഞങ്ങളുടെ ഡിസൈൻ, നിറങ്ങൾ, ലേഔട്ട്, ഘടന, രൂപം, കഥാപാത്രങ്ങൾ (സംസൂം ഉൾപ്പെടെ), എഴുത്തുകൾ, ആശയങ്ങൾ എന്നിവ പകർത്തുന്നതും തെറ്റായോ വ്യാജമായോ ഉപയോഗിക്കുന്നതും (ഉദാ. Sam Electronics ആണെന്ന് തോന്നിപ്പിക്കാൻ) അനുവദനീയമല്ല; യുഎഇ നിയമപ്രകാരം ശിക്ഷാർഹമാണ്.',
